{
  "lectura": "Buscás ficciones sobre espacios laborales y burocráticos donde la estructura de la vigilancia y el control institucional fracturan la percepción de la realidad de los personajes.",
  "sugerencias": [
    {
      "titulo": "Las intermitencias de la muerte",
      "autor": "José Saramago",
      "vinculo": "Trabaja la maquinaria estatal y el funcionamiento administrativo desde una lógica absurda que descoloca al lector a través de una voz coral y distante."
    },
    {
      "titulo": "Los lanzallamas",
      "autor": "Rachel Kushner",
      "vinculo": "Explora cómo las estructuras industriales y las corporaciones modernas modelan la subjetividad y el aislamiento de quienes forman parte de ellas."
    },
    {
      "titulo": "Los testamentos",
      "autor": "Margaret Atwood",
      "vinculo": "Utiliza múltiples puntos de vista para diseccionar el funcionamiento interno de una institución totalitaria que vigila y administra la información."
    },
    {
      "titulo": "Constellation",
      "autor": "Adrienne Celt",
      "vinculo": "Aborda la tensión entre la labor artística y la burocracia estatal bajo regímenes de control ideológico estricto."
    },
    {
      "titulo": "La oficina",
      "autor": "Leopoldo Brizuela",
      "vinculo": "Construye un clima de encierro y paranoia laboral donde el espacio de trabajo se vuelve una trampa psicológica opresiva."
    }
  ]
}
